sys_script_include.script:
var OptionProcessorAjax = Class.create();
OptionProcessorAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    updateSelectedOptions: function() {
        var recordSysId = this.getParameter('sysparm_record_sys_id');
        var tableName = this.getParameter('sysparm_table_name');
        var optionsData = this.getParameter('sysparm_options_data');

        gs.info("OptionProcessorAjax (Initial Params): SysId: " + recordSysId + ", Table: " + tableName + ", OptionsData: " + optionsData);

        if (!recordSysId || !tableName || !optionsData || recordSysId == '-1') {
            gs.error("OptionProcessorAjax: Missing or invalid parameters. SysId: " + recordSysId + ", Table: " + tableName + ", Options: " + optionsData);
            return "error: Missing or invalid parameters. Is the record saved?";
        }

        try {
            var optionsObject = JSON.parse(optionsData);
            var selectedOptionNames = []; // This will store your desired output: ['trade_date','settlement_date']

            // Iterate over the properties of the optionsObject
            for (var key in optionsObject) {
                // Ensure the key is a direct property of the object (not from prototype chain)
                if (optionsObject.hasOwnProperty(key)) {
                    // If the checkbox was checked (value is true)
                    if (optionsObject[key] === true) {
                        selectedOptionNames.push(key); // Add the backend name (key) to the array
                    }
                }
            }

            // Convert the array to a JSON string for storing in the field
            var finalOutput = JSON.stringify(selectedOptionNames); 

            gs.info("OptionProcessorAjax: Final Output for Description: " + finalOutput);

            var gr = new GlideRecord(tableName);
            if (gr.get(recordSysId)) {
                // Set the value of your field (e.g., description). This will now store the JSON array string.
                gr.setValue('description', finalOutput); 
                gr.update();
                gs.info("OptionProcessorAjax: Successfully updated record " + recordSysId + " with options: " + finalOutput);
                return "success";
            } else {
                gs.error("OptionProcessorAjax: Record not found for SysId: " + recordSysId + " on Table: " + tableName);
                return "error: Record not found.";
            }
        } catch (e) {
            gs.error("OptionProcessorAjax: Server-side error processing options for record " + recordSysId + " on table " + tableName + ". Error: " + e.getMessage() + ", Stack: " + e.stack);
            return "error: " + e.getMessage();
        }
    },


   updateIncidentComments: function() {
        var incidentSysIds = this.getParameter('sysparm_incident_sys_ids');
        var comments = this.getParameter('sysparm_comments');
        var sysIdArray = incidentSysIds.split(',');
        var grIncident;
        var success = true;

        for (var i = 0; i < sysIdArray.length; i++) {
            grIncident = new GlideRecord('incident');
            if (grIncident.get(sysIdArray[i])) {
                if (grIncident.work_notes) {
                    grIncident.work_notes = grIncident.work_notes + "\n" + comments;
                } else {
                    grIncident.work_notes = comments;
                }
                grIncident.update();
            } else {
                success = false;
            }
        }
        return success ? 'success' : 'error';
    },

    // --- IMPORTANT: REMOVE/COMMENT OUT THE FOLLOWING FUNCTION IF IT EXISTS ---
    // getFilteredIncidents: function() {
    //     // This function is NOT used in the iframe approach, as the iframe directly loads data.
    //     // Remove its entire body or comment it out to avoid confusion.
    //     // For example:
    //     // return JSON.stringify([]); // Return empty if you must keep it, but removing is cleaner.
    // },
    // *** REMOVE OR COMMENT OUT THIS FUNCTION (and any old searchIncidents function) ***
    // getFilteredIncidents: function() { /* ... old logic ... */ },

    // Function to update comments for selected incidents
    updateIncidentsComments: function() {
        var incidentSysIds = this.getParameter('sysparm_incident_sys_ids');
        var comments = this.getParameter('sysparm_comments');
        var updatedCount = 0;
        var errorMessages = [];

        if (!incidentSysIds || !comments) {
            return JSON.stringify({ success: false, message: 'Missing incident IDs or comments.' });
        }

        var sysIdArray = incidentSysIds.split(',');

        for (var i = 0; i < sysIdArray.length; i++) {
            var incGr = new GlideRecord('incident');
            if (incGr.get(sysIdArray[i])) {
                // Append to additional comments (work_notes)
                // Using work_notes.setJournalEntry(comments, true) appends without adding a new line if the previous entry was from the same user.
                // For simplicity and clear separation, we'll just append.
                // If you want to strictly append to 'comments' (customer visible), change 'work_notes' to 'comments'.
                // However, 'additional_comments' maps to 'comments' in the backend for customer-facing notes.
                // 'Work notes' maps to 'work_notes' for internal notes.
                // The image shows "Comments:", which typically maps to 'comments' (additional_comments).
                // Let's assume 'additional_comments' for the user-facing text box.
                incGr.comments = comments; // This will overwrite existing comments.
                                         // To append, you'd do: incGr.comments = incGr.comments + '\n' + comments;
                                         // Or, for journal fields, use setJournalEntry.
                                         // For the purpose of the image, it seems like a new entry.
                                         // Let's use work_notes for adding new entries, as it's more common for "adding" comments.
                                         // If you truly want to update the 'comments' field (which is usually a single-line string),
                                         // you might need different logic.
                                         // Given the context, 'additional_comments' (which is a journal field) is more likely.
                                         // Let's use work_notes for the update, as it's a journal field and allows appending.

                // To add to Additional Comments (customer visible journal field):
                incGr.setValue('comments', incGr.getValue('comments') + '\n' + comments); // Appends to the 'comments' journal field

                // To add to Work Notes (internal journal field):
                // incGr.setValue('work_notes', incGr.getValue('work_notes') + '\n' + comments);

                incGr.setWorkflow(false); // Do not run business rules
                incGr.autoSysFields(false); // Do not update system fields (updated, updated_by)
                var success = incGr.update();
                if (success) {
                    updatedCount++;
                } else {
                    errorMessages.push('Failed to update incident: ' + sysIdArray[i]);
                }
            } else {
                errorMessages.push('Incident not found: ' + sysIdArray[i]);
            }
        }

        if (errorMessages.length > 0) {
            return JSON.stringify({ success: false, message: errorMessages.join('; ') });
        } else {
            return JSON.stringify({ success: true, updatedCount: updatedCount });
        }
    },

    _privateFunction: function() {
        // Private functions (not callable from client)
    },


	getIncidents: function() {
        var keyword = this.getParameter('sysparm_keyword') || '';
        var gr = new GlideRecord('incident');
        gr.addQuery('active', true);
        if (keyword) {
            var qc = gr.addQuery('comments', 'CONTAINS', keyword);
            qc.addOrCondition('u_additional_comments', 'CONTAINS', keyword);
        }
        gr.query();

        var result = [];
        while (gr.next()) {
            result.push({
                sys_id: gr.getUniqueValue(),
                number: gr.getValue('number'),
                short_description: gr.getValue('short_description'),
                comments: gr.getValue('comments') || '',
                additional_comments: gr.getValue('u_additional_comments') || ''
            });
        }

        return JSON.stringify(result);
    },

    /**
     * Update comments for list of incidents
     */
    updateComments: function() {
        var sysIds = this.getParameter('sysparm_sys_ids') || '';
        var comment = this.getParameter('sysparm_comment') || '';

        if (!sysIds || !comment) return 'No records updated.';

        var idsArray = sysIds.split(',');
        var updated = 0;

        idsArray.forEach(function(id) {
            var gr = new GlideRecord('incident');
            if (gr.get(id)) {
                // Append to existing comments
                var currentComments = gr.getValue('comments') || '';
                var newComments = currentComments + '\n' + comment;
                gr.setValue('comments', newComments);
                gr.update();
                updated++;
            }
        });

        return updated + ' incidents updated.';
    },



    type: 'OptionProcessorAjax'
});
